const minPath = (grid, k) => {
    const N = grid.length;
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];

    // Find all cells with their values
    // For each step, we want the lexicographically smallest path
    // We use BFS-like approach but track all possible paths

    // Since k can be large, we need an efficient approach
    // At each step, from all current possible cells, we pick the ones
    // that have the minimum value among all neighbors, and continue

    // Start: all cells are possible starting points
    let candidates = [];
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            candidates.push([i, j]);
        }
    }

    let result = [];

    for (let step = 0; step < k; step++) {
        // Find the minimum value among all neighbors of all candidates
        let minVal = Infinity;
        let nextCandidates = [];

        if (step === 0) {
            // First step: we pick the cell itself (we start there)
            // Find minimum value among all candidates
            for (const [i, j] of candidates) {
                if (grid[i][j] < minVal) {
                    minVal = grid[i][j];
                }
            }
            for (const [i, j] of candidates) {
                if (grid[i][j] === minVal) {
                    nextCandidates.push([i, j]);
                }
            }
        } else {
            // For subsequent steps, we move to neighbors
            for (const [i, j] of candidates) {
                for (const [di, dj] of dirs) {
                    const ni = i + di;
                    const nj = j + dj;
                    if (ni >= 0 && ni < N && nj >= 0 && nj < N) {
                        if (grid[ni][nj] < minVal) {
                            minVal = grid[ni][nj];
                        }
                    }
