            }
            for (const [i, j] of candidates) {
                for (const [di, dj] of dirs) {
                    const ni = i + di;
                    const nj = j + dj;
                    if (ni >= 0 && ni < N && nj >= 0 && nj < N) {
                        if (grid[ni][nj] === minVal) {
                            nextCandidates.push([ni, nj]);
                        }
                    }
                }
            }
        }

        result.push(minVal);
        candidates = nextCandidates;
    }

    return result;
};
